// Durable, single-user bookmark store (JSON file with atomic writes).
// Central goal: nothing gets lost. All mutations persist immediately.

import { readFileSync, writeFileSync, renameSync, mkdirSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { normalizeUrl, urlKey, InvalidUrlError } from "./url.js";

const __dirname = dirname(fileURLToPath(import.meta.url));
const DEFAULT_FILE = join(__dirname, "..", "data", "bookmarks.json");

export class DuplicateError extends Error {
  constructor(existing) {
    super("A bookmark with this address already exists.");
    this.code = "duplicate";
    this.existing = existing;
  }
}
export class NotFoundError extends Error {
  constructor() {
    super("Bookmark not found.");
    this.code = "not_found";
  }
}

export class Store {
  constructor(file = process.env.BOOKMARKS_DATA || DEFAULT_FILE) {
    this.file = file;
    this.items = [];
    this.nextId = 1;
    this._load();
  }

  _load() {
    try {
      const raw = readFileSync(this.file, "utf8");
      const data = JSON.parse(raw);
      this.items = Array.isArray(data.items) ? data.items : [];
      this.nextId = Number.isInteger(data.nextId) ? data.nextId : this._computeNextId();
    } catch {
      this.items = [];
      this.nextId = 1;
    }
  }

  _computeNextId() {
    return this.items.reduce((m, b) => Math.max(m, b.id || 0), 0) + 1;
  }

  _save() {
    mkdirSync(dirname(this.file), { recursive: true });
    const tmp = this.file + ".tmp";
    writeFileSync(tmp, JSON.stringify({ nextId: this.nextId, items: this.items }, null, 2));
    renameSync(tmp, this.file); // atomic replace
  }

  // Test-only: clear all data. Guarded by the caller (never exposed in prod).
  reset() {
    this.items = [];
    this.nextId = 1;
    this._save();
  }

  list() {
    return this.items.map((b) => ({ ...b }));
  }

  get(id) {
    return this.items.find((b) => b.id === Number(id)) || null;
  }

  findByUrl(url, exceptId = null) {
    const key = urlKey(url);
    return this.items.find((b) => urlKey(b.url) === key && b.id !== exceptId) || null;
  }

  // fields: { url, title, description?, tags?, note?, image?, icon?, site? }
  create(fields) {
    const { url, host } = normalizeUrl(fields.url); // throws InvalidUrlError
    const dup = this.findByUrl(url);
    if (dup) throw new DuplicateError({ ...dup });
    const bm = {
      id: this.nextId++,
      url,
      host,
      site: fields.site || host,
      title: (fields.title || "").trim() || host,
      description: (fields.description || "").trim(),
      tags: normalizeTags(fields.tags),
      note: (fields.note || "").trim(),
      image: fields.image || null,
      icon: fields.icon || null,
      savedAt: Date.now(),
      readLater: false,
      archived: false,
    };
    this.items.unshift(bm);
    this._save();
    return { ...bm };
  }

  // Partial update. Editable: url, title, description, tags, note, readLater, archived.
  update(id, changes) {
    const bm = this.items.find((b) => b.id === Number(id));
    if (!bm) throw new NotFoundError();

    if (changes.url !== undefined) {
      const { url, host } = normalizeUrl(changes.url); // throws InvalidUrlError
      const clash = this.findByUrl(url, bm.id);
      if (clash) throw new DuplicateError({ ...clash });
      if (urlKey(url) !== urlKey(bm.url)) {
        // Site details follow the new address (SCN-008).
        bm.url = url;
        bm.host = host;
        bm.site = host;
        bm.image = null;
        bm.icon = null;
      } else {
        bm.url = url;
      }
    }
    if (changes.title !== undefined) bm.title = (changes.title || "").trim() || bm.title;
    if (changes.description !== undefined) bm.description = (changes.description || "").trim();
    if (changes.tags !== undefined) bm.tags = normalizeTags(changes.tags);
    if (changes.note !== undefined) bm.note = (changes.note || "").trim();
    if (changes.readLater !== undefined) bm.readLater = !!changes.readLater;
    if (changes.archived !== undefined) bm.archived = !!changes.archived;

    this._save();
    return { ...bm };
  }
}

function normalizeTags(tags) {
  let arr = [];
  if (Array.isArray(tags)) arr = tags;
  else if (typeof tags === "string") arr = tags.split(",");
  const seen = new Set();
  const out = [];
  for (const t of arr) {
    const v = String(t).trim();
    if (!v) continue;
    const k = v.toLowerCase();
    if (seen.has(k)) continue;
    seen.add(k);
    out.push(v);
  }
  return out;
}

export { InvalidUrlError };
// Page-detail collection (SCN-001, SCN-010).
// parseMetadata is a pure function (unit-tested against HTML fixtures).
// fetchMetadata performs the network request and degrades gracefully so saving
// stays possible even when a page's details cannot be read.

import { normalizeUrl, InvalidUrlError } from "./url.js";

function decodeEntities(s) {
  if (!s) return s;
  return s
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&#x27;/gi, "'")
    .replace(/&nbsp;/g, " ")
    .replace(/&#(\d+);/g, (_, d) => String.fromCharCode(parseInt(d, 10)))
    .trim();
}

function metaContent(html, matchers) {
  // Each matcher is a regex that captures the tag; we then read its content attr.
  for (const re of matchers) {
    const m = html.match(re);
    if (m) {
      const tag = m[0];
      const c = tag.match(/content\s*=\s*("([^"]*)"|'([^']*)')/i);
      if (c) return decodeEntities(c[2] ?? c[3] ?? "");
    }
  }
  return null;
}

function absolutize(href, baseUrl) {
  if (!href) return null;
  try {
    return new URL(href, baseUrl).href;
  } catch {
    return null;
  }
}

// Extract title, description, preview image, site name and icon from raw HTML.
export function parseMetadata(html, baseUrl) {
  html = String(html || "");
  const ogTitle = metaContent(html, [
    /<meta[^>]+property\s*=\s*["']og:title["'][^>]*>/i,
    /<meta[^>]+name\s*=\s*["']og:title["'][^>]*>/i,
  ]);
  let title = ogTitle;
  if (!title) {
    const t = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
    title = t ? decodeEntities(t[1].replace(/\s+/g, " ")) : "";
  }

  const description = metaContent(html, [
    /<meta[^>]+property\s*=\s*["']og:description["'][^>]*>/i,
    /<meta[^>]+name\s*=\s*["']description["'][^>]*>/i,
  ]) || "";

  const image = absolutize(
    metaContent(html, [
      /<meta[^>]+property\s*=\s*["']og:image["'][^>]*>/i,
      /<meta[^>]+name\s*=\s*["']og:image["'][^>]*>/i,
    ]),
    baseUrl
  );

  const siteName = metaContent(html, [
    /<meta[^>]+property\s*=\s*["']og:site_name["'][^>]*>/i,
  ]);

  // Favicon: prefer a declared <link rel="...icon...">, else the site's default.
  let iconHref = null;
  const linkRe = /<link\b[^>]*>/gi;
  let lm;
  while ((lm = linkRe.exec(html))) {
    const tag = lm[0];
    if (/rel\s*=\s*("[^"]*icon[^"]*"|'[^']*icon[^']*')/i.test(tag)) {
      const hrefM = tag.match(/href\s*=\s*("([^"]*)"|'([^']*)')/i);
      if (hrefM) {
        iconHref = hrefM[2] ?? hrefM[3];
        break;
      }
    }
  }
  let icon = absolutize(iconHref, baseUrl);
  if (!icon) {
    try {
      icon = new URL("/favicon.ico", baseUrl).href;
    } catch {
      icon = null;
    }
  }

  let host = "";
  try {
    host = new URL(baseUrl).hostname.replace(/^www\./, "");
  } catch {
    /* baseUrl already validated by caller */
  }

  return {
    title: title || host,
    description,
    image: image || null,
    icon: icon || null,
    site: siteName || host,
  };
}

// Fetch a URL and return collected metadata.
// { ok:true, url, host, title, description, image, icon, site }
//   on success, or
// { ok:false, url, host, reason } when the page's details cannot be read.
// Throws InvalidUrlError only when the address itself is unusable.
export async function fetchMetadata(input, { timeoutMs = 8000, fetchImpl = fetch } = {}) {
  const { url, host } = normalizeUrl(input); // throws InvalidUrlError on bad input
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const res = await fetchImpl(url, {
      signal: controller.signal,
      redirect: "follow",
      headers: { "user-agent": "BookmarksApp/1.0 (+private)" },
    });
    if (!res.ok) return { ok: false, url, host, reason: "http_" + res.status };
    const ctype = res.headers.get("content-type") || "";
    if (!/text\/html|application\/xhtml/i.test(ctype)) {
      return { ok: false, url, host, reason: "not_html" };
    }
    const html = await res.text();
    const meta = parseMetadata(html, url);
    return { ok: true, url, host, ...meta };
  } catch (err) {
    return { ok: false, url, host, reason: err && err.name === "AbortError" ? "timeout" : "unreachable" };
  } finally {
    clearTimeout(timer);
  }
}

export { InvalidUrlError };
// URL normalisation and validation shared by the API and metadata fetcher.
// Approved behaviour (SCN-010, SCN-008): a missing scheme is assumed https, and
// text that is not a usable web address is rejected.

export class InvalidUrlError extends Error {
  constructor(message = "That doesn't look like a web address.") {
    super(message);
    this.code = "invalid_url";
  }
}

// Returns { url, host } with url normalised (https:// added when the scheme is
// omitted) and host being the hostname without a leading "www.".
// Throws InvalidUrlError when the input cannot be a real web address.
export function normalizeUrl(input) {
  const raw = String(input == null ? "" : input).trim();
  if (!raw) throw new InvalidUrlError();
  const withScheme = /^[a-z][a-z0-9+.-]*:\/\//i.test(raw) ? raw : "https://" + raw;
  let u;
  try {
    u = new URL(withScheme);
  } catch {
    throw new InvalidUrlError();
  }
  if (u.protocol !== "http:" && u.protocol !== "https:") throw new InvalidUrlError();
  const host = u.hostname.replace(/^www\./, "");
  if (!host) throw new InvalidUrlError();
  // A real web address has a dotted host, or is localhost / an IP address.
  // This rejects bare words like "hello" or "not a url".
  const isIp = /^\d{1,3}(\.\d{1,3}){3}$/.test(host) || host.includes(":");
  if (host !== "localhost" && !isIp && host.indexOf(".") < 0) throw new InvalidUrlError();
  return { url: u.href, host };
}

// Case-insensitive comparison key for duplicate detection.
export function urlKey(url) {
  return String(url).trim().toLowerCase();
}
